// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PersonAttribute) predicate.PersonAttribute {
	return predicate.PersonAttribute(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PersonAttribute) predicate.PersonAttribute {
	return predicate.PersonAttribute(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PersonAttribute) predicate.PersonAttribute {
	return predicate.PersonAttribute(sql.NotPredicates(p))
}
